/* Explications des QCM — quart */
C200.expl({
 "quart.q.1amknnk": "Le GPS calcule ses positions dans le système WGS 84. Les cartes modernes utilisent le même système.",
 "quart.q.1tzhwrh": "Si la carte utilise un autre système, la position GPS placée sur la carte peut être décalée de plusieurs dizaines de mètres.",
 "quart.q.qoo218": "La carte indique la correction à faire (en minutes de latitude et de longitude) pour passer du point GPS à la carte.",
 "quart.q.4rpyo0": "Comparer le GPS, le radar et la carte permet de voir tout de suite si un appareil se trompe.",
 "quart.q.19uc1b3": "Le radar et l'ECDIS ont besoin de la vitesse (loch ou GPS) : une mauvaise vitesse donne de faux calculs d'abordage.",
 "quart.q.1n3jan2": "Le loch mesure la vitesse par rapport à l'eau (vitesse surface).",
 "quart.q.1a4zbmv": "Le GPS mesure le déplacement par rapport à la Terre : c'est la vitesse fond.",
 "quart.q.cnd390": "Dans une passerelle fermée, on entend mal dehors : le détecteur de sons transmet les signaux sonores des autres navires.",
 "quart.q.1ykvsra": "L'alarme d'écart de cap sonne si le navire s'éloigne trop du cap choisi (pilote qui décroche, barre en panne…).",
 "quart.q.2xb6pr": "Le BNWAS demande à l'officier de quart d'appuyer régulièrement sur un bouton : s'il ne le fait pas, c'est qu'il dort ou n'est plus là.",
 "quart.q.18cuezg": "Si l'officier ne répond pas, l'alarme se déclenche chez le capitaine ou un autre officier, qui monte à la passerelle.",
 "quart.q.116hbnk": "Cette alarme signale qu'un feu de navigation du navire est grillé ou éteint.",
 "quart.q.mb1to3": "L'indicateur d'angle de barre montre de combien le gouvernail est tourné. On vérifie qu'il est juste partout où on peut le lire.",
 "quart.q.1o0fi6u": "Les instruments météo (baromètre, anémomètre, température de l'eau) sont aussi contrôlés avant de partir.",
 "quart.q.n0bam7": "Pour le pilote automatique, on vérifie les moteurs de barre, les compas, le compas qu'il suit et ses réglages.",
 "quart.q.bz76jy": "Le réglage « rudder » dit combien de barre le pilote donne pour corriger un écart de cap.",
 "quart.q.19174ck": "Par mauvais temps, le navire fait des petites embardées : le réglage « yawing » évite que le pilote corrige sans arrêt.",
 "quart.q.1wxxs4t": "On compare régulièrement le cap gyro et le cap magnétique : un écart anormal montre qu'un compas se trompe.",
 "quart.q.f3d03u": "Un appareil sur une mauvaise échelle (radar à trop longue ou trop courte portée) peut cacher un danger.",
 "quart.q.75p6x0": "La redondance, c'est avoir un appareil de secours, essayé, prêt à remplacer celui qui tombe en panne.",
 "quart.q.19mrgdn": "L'anti-clutter enlève les taches dues aux vagues (mer) ou à la pluie sur l'écran radar.",
 "quart.q.13em9tp": "Trop fort, l'anti-clutter mer efface aussi les petits échos près du navire : un petit bateau peut disparaître.",
 "quart.q.1npwaci": "On règle le NAVTEX sur les stations de la zone où l'on navigue, pour recevoir les bons messages de sécurité.",
 "quart.q.gtofsh": "Certaines cartes viennent de relevés anciens, moins précis que le GPS : le GPS est juste, mais la carte peut être fausse.",
 "quart.q.1sopdkj": "Le GPS est précis, mais si la carte est imprécise, le navire peut paraître en sécurité alors qu'il est près d'un danger.",
 "quart.q.1qgnkd0": "Les contrôles sont écrits au brouillon passerelle et au cahier de variation (les erreurs des compas).",
 "quart.q.18kqttb": "La barre doit être essayée dans les 12 heures qui précèdent le départ.",
 "quart.q.z0o0cq": "On met la barre d'un bord à l'autre, on vérifie les indicateurs d'angle et les moteurs de barre.",
 "quart.q.1dt0idx": "Le compas gyroscopique met plusieurs heures à se stabiliser : on le démarre longtemps avant le départ.",
 "quart.q.jkhiq1": "On teste les liaisons passerelle-machine, avec l'avant et l'arrière (postes de manœuvre) et la VHF.",
 "quart.q.12pzv1f": "Le sifflet et les feux de navigation doivent fonctionner avant de partir.",
 "quart.q.fuyt16": "Les tirants d'eau avant et arrière donnent l'assiette et la profondeur nécessaire pour sortir en sécurité.",
 "quart.q.srckca": "On met les horloges de la passerelle à l'heure du GPS, qui est très précise.",
 "quart.q.1o27afk": "On essaie les commandes de la machine (télégraphe) avec la machine, avant de larguer les amarres.",
 "quart.q.nikxl2": "La carte de sortie du port doit être prête et à jour, avec la route tracée.",
 "quart.q.svb2pj": "Le sondeur est allumé dès avant le départ, car c'est près des côtes que la profondeur est la plus critique.",
 "quart.q.jxdtgs": "L'AIS envoie aux autres la destination, le tirant d'eau et l'heure d'arrivée : on vérifie qu'ils sont justes.",
 "quart.q.8eio9p": "Les portes étanches et les ouvertures de la coque sont fermées et vérifiées avant de partir : c'est vital en cas de voie d'eau.",
 "quart.q.17f3keo": "Avant de partir, le capitaine vérifie que la cargaison est bien attachée et que la stabilité a été calculée.",
 "quart.q.ywi31g": "La liste de toutes les personnes à bord est obligatoire avant le départ : en cas d'accident, on sait qui chercher.",
 "quart.q.jrcx3x": "Le contrôle de sûreté peut comprendre une fouille pour trouver des passagers clandestins.",
 "quart.q.1upuejy": "Les erreurs des compas sont notées au cahier de variation.",
 "quart.q.3layh2": "Les vecteurs de l'ARPA dépendent de la vitesse utilisée (fond ou surface) : il faut savoir laquelle pour bien juger le risque.",
 "quart.q.1mzk79w": "L'ECDIS doit avoir les bonnes cartes à jour pour toute la route, et ses alarmes réglées.",
 "quart.q.i4qnnr": "Une panne avant le départ peut être dangereuse : on la note et on prévient le capitaine, qui décide.",
 "quart.q.dxch2c": "La check-list évite d'oublier un contrôle important.",
 "quart.q.qnbcpx": "L'ancre est prête à mouiller pendant la sortie du port : c'est le secours en cas de panne de machine.",
 "quart.q.83yc7y": "La machine confirme à la passerelle qu'elle est prête avant qu'on largue les amarres.",
 "quart.q.lu1ohf": "On remet au pilote la fiche pilote / capitaine, qui donne les informations utiles sur le navire.",
 "quart.q.1qar2sn": "L'atterrissage est le moment où l'on arrive du large et où l'on reconnaît la côte pour passer en navigation côtière.",
 "quart.q.14o0ubc": "On choisit si possible une heure où le soleil n'éblouit pas, pour bien voir la côte et les amers.",
 "quart.q.xwf129": "Sur une côte difficile, on préfère arriver de jour : on voit mieux les amers et les dangers.",
 "quart.q.cfopkd": "On prépare sur la carte où l'on doit voir chaque phare, amer, écho radar ou sonde : on saura vite si on est en avance ou en retard.",
 "quart.q.hz2t2d": "On prépare les alignements, les relèvements et les caractéristiques des feux qu'on va rencontrer.",
 "quart.q.1j1atsx": "Un alignement, ce sont deux repères vus l'un derrière l'autre : on est alors sur une ligne connue.",
 "quart.q.1ivyklv": "Un alignement est précis à partir d'une distance d'environ 7 fois l'écart entre les deux repères.",
 "quart.q.1s97lye": "7 × 300 m = 2 100 m, soit 2,1 km.",
 "quart.q.1ibebm8": "Si la marque avant passe à droite de la marque arrière, tu es à gauche de l'alignement : il faut revenir à droite.",
 "quart.q.17762ij": "Si la marque avant passe à gauche, tu es à droite de l'alignement : il faut revenir à gauche.",
 "quart.q.o8t3e5": "La marque arrière se décale du même côté que toi : à droite, tu es à droite de l'alignement et tu reviens à gauche.",
 "quart.q.oi15cd": "Les deux marques l'une au-dessus de l'autre : tu es pile sur l'alignement.",
 "quart.q.giuujl": "Au radar, on utilise l'EBL (ligne de relèvement) et le VRM (cercle de distance) pour tracer et suivre un alignement.",
 "quart.q.1iamsob": "L'ECDIS peut aussi afficher la ligne de l'alignement sur la carte électronique.",
 "quart.q.1ng053h": "La couleur du secteur dans lequel on voit le feu dit dans quelle zone on se trouve.",
 "quart.q.1jwm6tk": "La portée géographique dépend de la hauteur du feu et de la hauteur de l'œil, à cause de la rondeur de la Terre.",
 "quart.q.1sx6dnp": "Portée géographique (milles) ≈ 2,08 × (√hauteur du feu + √hauteur de l'œil), hauteurs en mètres.",
 "quart.q.14c30ta": "2,08 × (√25 + √16) = 2,08 × (5 + 4) ≈ 19 milles.",
 "quart.q.h65urx": "Plus l'œil est haut, plus on voit loin au-dessus de la courbure de la Terre.",
 "quart.q.1s99y3g": "Le lever d'un feu, c'est l'instant où il apparaît au-dessus de l'horizon.",
 "quart.q.14udj36": "Au lever, on est à la portée géographique du feu : distance connue + relèvement = un point.",
 "quart.q.10uoqcx": "Une côte haute renvoie bien les ondes radar : on la voit de loin.",
 "quart.q.fdzamt": "Une côte basse et sableuse renvoie mal les ondes : elle apparaît tard au radar.",
 "quart.q.18kme8r": "On prévoit le moment où le sondeur doit passer une certaine profondeur : c'est un contrôle de la position.",
 "quart.q.11fklcc": "Arriver trop tôt sur une profondeur prévue montre une erreur de position : on vérifie et on prévient le capitaine.",
 "quart.q.193e4ye": "Si un amer attendu n'apparaît pas, la position est peut-être fausse : on prévient le capitaine et on vérifie par d'autres moyens.",
 "quart.q.1amjb3": "On reconnaît un phare à son rythme et à sa période, mesurés au chronomètre.",
 "quart.q.1vpyjhy": "La machine est prête à manœuvrer avant l'atterrissage : il faudra peut-être ralentir ou s'arrêter.",
 "quart.q.1g5vf40": "En approchant, on passe aux cartes plus détaillées (plus grande échelle) qui montrent mieux les dangers.",
 "quart.q.yq9rnb": "Un alignement permet de suivre un chenal ou une passe étroite avec précision.",
 "quart.q.woz0to": "Un alignement est une droite de position très précise, sans erreur de compas.",
 "quart.q.kcsjci": "Un relèvement au compas sur un amer donne une droite sur laquelle se trouve le navire.",
 "quart.q.1sho4a6": "Il faut au moins deux droites qui se croisent pour avoir un point ; une troisième permet de vérifier.",
 "quart.q.f5ga01": "Trois droites forment un petit triangle : plus il est petit, plus le point est sûr.",
 "quart.q.tjtugn": "Une distance radar donne un cercle autour de l'objet : le navire est quelque part sur ce cercle.",
 "quart.q.14jq1vb": "Le secteur rouge d'un feu couvre souvent un danger : si on le voit, on vérifie sa position.",
 "quart.q.86nvd5": "On écoute la VHF du port et les avis urgents (AVURNAV) pour connaître les dernières informations locales.",
 "quart.q.1h78ow9": "L'atterrissage est délicat (côte, trafic, dangers) : le capitaine est souvent présent à la passerelle.",
 "quart.q.47b5f8": "Un alignement n'est sûr que sur la partie montrée par la carte : en dehors, il peut passer sur des dangers.",
 "quart.q.1bqlbjt": "Se tromper d'amer donne un faux point : on l'identifie avec certitude grâce à la carte et aux Instructions nautiques.",
 "quart.q.urytdu": "Le soleil dans les yeux empêche de bien voir la côte : on peut changer l'heure d'arrivée.",
 "quart.q.kzrug9": "La profondeur mesurée doit correspondre à la carte, en ajoutant la hauteur de marée. Sinon, la position est peut-être fausse.",
 "quart.q.1pfy148": "Profondeur réelle = sonde de la carte + hauteur de marée = 18 + 2 = 20 m.",
 "quart.q.vtnhpf": "De jour, un alignement est fait de deux repères bien visibles : balises, tourelles, ou un clocher et un phare.",
 "quart.q.1ln92hh": "Le feu arrière est plus haut que le feu avant, pour qu'on voie les deux l'un au-dessus de l'autre.",
 "quart.q.z9bdb2": "La carte montre la ligne de l'alignement avec sa direction en degrés vrais.",
 "quart.q.150pjdo": "L'atterrissage est un moment à risque : on renforce la veille.",
 "quart.q.dn4hn9": "On prévient la machine à l'avance et l'équipage pour qu'ils soient prêts à la manœuvre.",
 "quart.q.3ptxzi": "La détresse : un danger grave et immédiat qui demande de l'aide tout de suite.",
 "quart.q.11j9ctg": "Naufrage, abandon du navire, homme à la mer, incendie grave : ce sont des cas de détresse.",
 "quart.q.rlkmye": "Un appel de détresse passe avant toutes les autres communications.",
 "quart.q.b70n0t": "On coupe ce qui peut brouiller et on écoute la fréquence de l'alerte pour bien recevoir le message.",
 "quart.q.rgtaye": "Le capitaine doit aller porter secours au plus vite, s'il peut le faire sans danger grave pour son navire.",
 "quart.q.12d5501": "On aide toute personne en danger en mer, quelle que soit sa nationalité ou sa situation.",
 "quart.q.6oyhh9": "S'il ne peut pas aider, le capitaine écrit pourquoi au journal de bord et prévient le CROSS (MRCC).",
 "quart.q.3ri60p": "En France, les centres de coordination du sauvetage (MRCC) sont les CROSS.",
 "quart.q.1hrrs19": "Le CROSS (MRCC) ou le capitaine du navire en détresse peut demander à un navire précis de venir aider.",
 "quart.q.1g9wzsk": "Quand un navire a été désigné pour aider, ou que l'aide n'est plus nécessaire, les autres sont libérés.",
 "quart.q.lq1ybz": "Les personnes sauvées sont traitées avec humanité et débarquées dès que possible dans un lieu sûr.",
 "quart.q.1ljibhr": "SMDSM en anglais : GMDSS (Global Maritime Distress and Safety System).",
 "quart.q.132xkbp": "Le SMDSM relie les navires, les satellites et les stations côtières pour faire passer les alertes jusqu'aux secours.",
 "quart.q.2450gq": "Le canal 16 est le canal de détresse en phonie (à la voix).",
 "quart.q.n09xl6": "Le canal 70 est réservé à l'ASN (appels numériques). On ne parle pas dessus.",
 "quart.q.1eteyq5": "En MF, la détresse à la voix se fait sur 2 182 kHz.",
 "quart.q.5tnjkw": "Un message de détresse commence par MAYDAY, dit trois fois.",
 "quart.q.1y730qb": "PAN PAN = urgence : problème grave mais pas de danger de mort immédiat.",
 "quart.q.r0pma9": "SÉCURITÉ = message important pour la navigation ou la météo.",
 "quart.q.1q1alw3": "MAYDAY RELAY : une station retransmet le message de détresse d'un autre navire.",
 "quart.q.1wwy2ch": "SEELONCE MAYDAY : la station qui dirige les secours impose le silence sur la fréquence aux autres.",
 "quart.q.1ai2r55": "SEELONCE FEENEE : la détresse est terminée, on peut de nouveau utiliser la fréquence normalement.",
 "quart.q.rcgubl": "La RLS (EPIRB en anglais) est la balise de détresse qui émet sur 406 MHz vers les satellites.",
 "quart.q.op3kke": "Les balises de détresse (RLS) sont reçues par les satellites Cospas-Sarsat, qui transmettent l'alerte aux secours.",
 "quart.q.1e0wrp7": "Le SART répond aux radars en bande X des sauveteurs : il apparaît sur leur écran et les guide vers le radeau.",
 "quart.q.1p3e4km": "Le SART dessine une ligne de 12 points vers l'extérieur de l'écran ; le point le plus proche du centre montre sa position.",
 "quart.q.1mf3zrc": "Après une alerte ASN, le message de détresse suit à la voix sur le canal 16 : on l'écoute et on se prépare à aider.",
 "quart.q.1bu6byy": "Le manuel IAMSAR (volume III, gardé à bord) explique comment participer à une recherche et un sauvetage.",
 "quart.q.r6ywq8": "L'OSC est le navire désigné pour diriger les recherches sur place, sous l'autorité du CROSS.",
 "quart.q.1rifanl": "La convention SAR de 1979 organise la recherche et le sauvetage en mer dans le monde.",
 "quart.q.1e2ttgd": "Ne pas aider quelqu'un en danger alors qu'on le pouvait est un délit puni par la loi.",
 "quart.q.p4eimo": "On donne au CROSS son heure d'arrivée prévue (ETA) et on prépare tout pour récupérer les naufragés.",
 "quart.q.1w63ywu": "On prépare tout ce qui sert à remonter les gens : échelle de pilote, filets, bouées, embarcation et une équipe.",
 "quart.q.1qragzp": "Après un séjour dans l'eau froide, le corps est trop froid (hypothermie) : on réchauffe doucement et on garde la personne allongée.",
 "quart.q.66lj8h": "Les signaux visuels de détresse : fusées rouges, feux à main rouges, fumée orange.",
 "quart.q.1425jxa": "Une alerte peut arriver par la VHF (ASN), une balise RLS, un satellite ou des signaux visuels.",
 "quart.q.4oox3d": "La détresse passe avant tous les autres messages radio.",
 "quart.q.61gghk": "Le plus utile pour les secours : nom du navire, position, ce qui se passe et l'aide demandée.",
 "quart.q.qkqomk": "On donne la position en latitude et longitude, ou par un relèvement et une distance depuis un point connu (un phare, un cap).",
 "quart.q.sq1y09": "Le capitaine du navire en détresse peut libérer les navires dont il n'a plus besoin.",
 "quart.q.1afw6ie": "Une fausse alerte doit être annulée tout de suite auprès du CROSS, pour ne pas lancer des secours pour rien.",
 "quart.q.1szf51r": "Homme à la mer : on ne le quitte pas des yeux, on lance une bouée et on enregistre la position (touche MOB).",
 "quart.q.jj1sul": "La touche MOB du GPS ou de l'ECDIS enregistre la position exacte au moment de la chute : on pourra y revenir.",
 "quart.q.p9teyh": "Les personnes sauvées doivent être débarquées au plus vite dans un lieu sûr.",
 "quart.q.p106bz": "L'obligation d'aider passe avant tout : le capitaine n'a pas besoin de l'accord de l'armateur.",
 "quart.q.1w0kgx8": "On note au journal toutes les heures, positions, actions et messages : c'est la mémoire et la preuve de l'opération.",
 "quart.q.dp73p8": "En France, c'est le CROSS (centre de coordination du sauvetage) qui dirige les opérations.",
 "quart.q.tmk6fz": "Pour organiser les recherches, le CROSS doit connaître la position, la vitesse, l'heure d'arrivée et les moyens de chaque navire.",
 "quart.q.sip3p4": "Le journal passerelle est aussi appelé livre de bord.",
 "quart.q.1h132ag": "On note l'heure, le cap vrai, le cap magnétique et les erreurs des compas : on peut ainsi reconstituer la route.",
 "quart.q.lrldfp": "On note le cap magnétique toutes les heures, pour suivre l'accord entre les compas.",
 "quart.q.4f250c": "Les points tournants (changements de route prévus) sont notés au journal.",
 "quart.q.13db97o": "La météo (vent, mer, pression, visibilité) est notée au journal passerelle.",
 "quart.q.394nzo": "Le point de midi et l'heure d'arrivée prévue (ETA) sont notés au journal passerelle.",
 "quart.q.nmdxpy": "Le comportement du navire (roulis, tangage, embarquement d'eau) se note au journal passerelle.",
 "quart.q.5kn00s": "Tout accident se note au journal passerelle, avec l'heure exacte.",
 "quart.q.cpy6gp": "Les changements d'heure (fuseaux) se notent au journal passerelle.",
 "quart.q.15zs8rj": "Les essais de barre et d'alarmes sont notés au journal passerelle : ça prouve qu'ils ont été faits.",
 "quart.q.6mws3f": "L'officier de quart signe ses quarts et le capitaine vise le journal.",
 "quart.q.1hr3418": "Les alarmes machine entendues à la passerelle sont notées au journal.",
 "quart.q.1f3zlzr": "Le journal est un document officiel : on écrit au stylo, on n'efface jamais ; une erreur se barre d'un trait et on signe.",
 "quart.q.k6l7a3": "Le journal sert de preuve (enquête, assurance, tribunal) : arracher une page le rend suspect.",
 "quart.q.cd05a1": "Les consignes permanentes sont écrites par le capitaine ou la compagnie : ce sont les règles de quart à respecter.",
 "quart.q.14lzans": "Le Code ISM impose à la compagnie un système écrit de sécurité, dont font partie les consignes permanentes.",
 "quart.q.sjk1nn": "Le Code ISM porte sur la gestion de la sécurité et de la prévention de la pollution par la compagnie et le navire.",
 "quart.q.1mcjiaq": "Le brouillon passerelle note toute la manœuvre de départ, de l'appel de l'équipage jusqu'à la route libre.",
 "quart.q.15lrj4t": "À l'arrivée, il note la manœuvre depuis la fin de route libre jusqu'au « terminé machine ».",
 "quart.q.1985evr": "« Route libre » : la manœuvre est finie, on passe à la navigation normale.",
 "quart.q.dyhs3b": "« Terminé machine » : on n'a plus besoin des moteurs pour manœuvrer, la manœuvre est finie.",
 "quart.q.1mm5jpf": "Le cahier de variation garde les erreurs mesurées du compas gyroscopique et du compas magnétique.",
 "quart.q.1du4j3l": "On mesure les erreurs des compas en relevant un alignement, ou un astre bas (soleil au lever, étoiles), dont on connaît la direction exacte.",
 "quart.q.1tm5z0k": "Variation = déclinaison (due au lieu) + déviation (due au navire).",
 "quart.q.1r6dxqs": "La déclinaison dépend du lieu sur la Terre et change un peu chaque année.",
 "quart.q.1pdev32": "La déviation vient du fer et de l'électricité du navire : elle change selon le cap.",
 "quart.q.1me22ww": "La fiche pilote / capitaine donne au pilote les informations sur le navire, et le pilote donne son plan.",
 "quart.q.oeze9t": "On y trouve les dimensions, la puissance, la vitesse, la giration : ce qu'il faut savoir pour manœuvrer le navire.",
 "quart.q.1gqmrsl": "Le pilote et le capitaine la signent tous les deux.",
 "quart.q.1t6qr58": "En cas d'accident, le capitaine s'appuie sur les documents de quart pour écrire son rapport de mer.",
 "quart.q.gc93cy": "Le rapport de mer est le récit officiel, par le capitaine, d'un événement grave arrivé en mer (avarie, accident).",
 "quart.q.p615ki": "Le capitaine écrit ses consignes pour la nuit dans le cahier d'ordres de nuit ; chaque officier le lit et le signe.",
 "quart.q.ric5lz": "La veille radio et les messages de détresse se notent au journal radio.",
 "quart.q.zxi0g6": "Le registre des hydrocarbures (MARPOL) note tous les transferts et rejets de gasoil, d'huile et d'eaux mazouteuses.",
 "quart.q.hwb0sw": "Le registre des ordures (MARPOL) note les rejets autorisés et les dépôts de déchets à terre.",
 "quart.q.iaf369": "L'heure doit être précise : c'est elle qui permet de reconstituer les événements.",
 "quart.q.1k124vk": "On barre d'un trait, en laissant lisible ce qui était écrit, et on signe. On n'efface jamais.",
 "quart.q.1q4k8zi": "Un journal électronique doit être sauvegardé et on ne doit pas pouvoir modifier une entrée sans que ça se voie.",
 "quart.q.bptz7x": "On note le changement de fuseau horaire et l'heure à laquelle il est fait.",
 "quart.q.h6w1fs": "À chaque changement de route, on note aussi les erreurs des compas au journal.",
 "quart.q.14j8c1d": "Le brouillon passerelle note toute la manœuvre d'appareillage, minute par minute.",
 "quart.q.548t43": "Le cahier de variation garde l'historique des erreurs des compas.",
 "quart.q.qzdiiu": "La fiche pilote / capitaine est échangée avec le pilote.",
 "quart.q.1ajgefd": "Les consignes permanentes donnent les règles à respecter en tout temps à la passerelle.",
 "quart.q.j7scfy": "On note tout de suite l'accident au journal passerelle, avec l'heure exacte.",
 "quart.q.4qe4ot": "Les autorités peuvent demander le journal pour une enquête ou un contrôle.",
 "quart.q.1f27yp1": "C'est une preuve : on le garde longtemps, à bord puis dans les archives de la compagnie.",
 "quart.q.mts6fo": "Le capitaine décide s'il faut un quart permanent à la passerelle au mouillage, selon la météo, le trafic et l'endroit.",
 "quart.q.1jhlcja": "Au mouillage, le plus grand danger est que l'ancre ne tienne plus et que le navire dérive (chasse).",
 "quart.q.378qy0": "« Chasser » : l'ancre glisse sur le fond, elle ne tient plus, et le navire dérive.",
 "quart.q.sgdgy2": "On vérifie avec tous les moyens : radar, GPS, ECDIS, sondeur, alarme de mouillage et relèvements d'amers.",
 "quart.q.dv9pwc": "Si les relèvements d'amers fixes changent, c'est que le navire bouge : il chasse.",
 "quart.q.1hbn24o": "L'alarme sonne si le navire sort du cercle prévu autour du point de mouillage.",
 "quart.q.3lie29": "Le cercle d'évitage : la zone dans laquelle le navire tourne autour de son ancre avec le vent et le courant.",
 "quart.q.ddgoir": "Le navire peut tourner autour de l'ancre jusqu'à la longueur de chaîne plus sa propre longueur.",
 "quart.q.pmvves": "Un navire bien tenu reste face au vent. S'il se met en travers, son ancre ne le retient plus : il chasse.",
 "quart.q.19d0unw": "Une chaîne qui vibre ou donne des saccades montre que l'ancre ripe sur le fond.",
 "quart.q.14jh8tl": "Au mouillage, le navire devrait bouger peu et dans tous les sens. Une vitesse stable dans une direction montre qu'il dérive.",
 "quart.q.1g18bfj": "On prévient le capitaine et on fait préparer la machine pour pouvoir manœuvrer vite.",
 "quart.q.68n7fv": "La machine doit pouvoir démarrer rapidement si l'ancre chasse : l'équipe machine reste disponible.",
 "quart.q.bum27i": "Pour arrêter une chasse : filer plus de chaîne, mouiller la deuxième ancre, ou relever et remouiller ailleurs.",
 "quart.q.1kq52m2": "Par beau temps, on file au moins 3 à 4 fois la profondeur de chaîne.",
 "quart.q.15v3t2q": "Par mauvais temps, on file plus de chaîne : son poids aide l'ancre à tenir.",
 "quart.q.1p14taq": "Les rondes (incendie, voies d'eau, sûreté) continuent au mouillage.",
 "quart.q.1ed6dmy": "Les règles contre la pollution s'appliquent toujours, au mouillage comme en route.",
 "quart.q.1kgz63": "Un changement de vent ou de courant peut faire chasser l'ancre : on surveille la météo.",
 "quart.q.ll8h58": "On surveille ce qui s'approche : navire, embarcation suspecte, ou l'annexe du bord qui revient.",
 "quart.q.3dau91": "La VHF du port donne les consignes locales et permet de savoir quand le pilote arrive.",
 "quart.q.1arf7cc": "Moins de 50 m : un seul feu blanc visible tout autour.",
 "quart.q.qkd5ov": "50 m ou plus : un feu blanc à l'avant (plus haut) et un à l'arrière (plus bas), visibles tout autour.",
 "quart.q.ahx4rh": "Le feu de mouillage avant est plus haut que celui de l'arrière.",
 "quart.q.k24rni": "À partir de 100 m, on doit en plus éclairer ses ponts.",
 "quart.q.1fke977": "De jour au mouillage : une boule noire à l'avant.",
 "quart.q.k9rbf3": "Au mouillage, on éteint les feux de route (côté et mât) et on allume les feux de mouillage.",
 "quart.q.1iw91zj": "Moins de 100 m au mouillage dans la brume : volée de cloche d'environ 5 secondes, au moins chaque minute.",
 "quart.q.mhhkvt": "100 m et plus : cloche à l'avant, puis gong à l'arrière, au moins chaque minute.",
 "quart.q.1rftqx8": "Bref-prolongé-bref avertit un navire qui s'approche : « je suis au mouillage, attention ».",
 "quart.q.pjia3g": "Échoué : 3 coups de cloche distincts, la volée de cloche, puis 3 coups distincts.",
 "quart.q.yd0m45": "On note le point de mouillage, la longueur de chaîne et chaque vérification de position.",
 "quart.q.qqvbv4": "On relève 2 ou 3 amers fixes, faciles à reconnaître, pour vérifier ensuite qu'on ne bouge pas.",
 "quart.q.hmf5aw": "Une bouée est tenue par une chaîne et bouge avec le courant : ce n'est pas un repère fixe.",
 "quart.q.5yg2ht": "La marée change la profondeur et la façon dont la chaîne tire : on la surveille.",
 "quart.q.qtfylf": "Un navire trop proche peut nous heurter en évitant : on l'appelle à la VHF et on prévient le capitaine.",
 "quart.q.1cwkew": "Une ancre qui « dérape » sur le fond annonce une chasse : on prévient tout de suite le capitaine.",
 "quart.q.901k8z": "Au mouillage, les dangers existent toujours (chasse, abordage, météo) : le quart demande autant d'attention.",
 "quart.q.whupgk": "Une embarcation suspecte la nuit peut être une menace : on suit le plan de sûreté et on prévient le capitaine.",
 "quart.q.12yvit0": "On surveille l'annexe pour la sécurité des personnes à bord, surtout la nuit ou par mauvais temps.",
 "quart.q.j5x4nr": "Si le vent forcit, le capitaine peut filer plus de chaîne ou partir pour se mettre à l'abri.",
 "quart.q.962n9b": "Au mouillage, le navire se place naturellement face au vent ou au courant.",
 "quart.q.10h7nqo": "L'ECDIS peut tracer le cercle d'évitage et sonner si le navire en sort.",
 "quart.q.yvf9sc": "Au mouillage, la veille visuelle continue en permanence.",
 "quart.q.jfrl48": "À la relève, on vérifie que le navire est toujours dans son cercle d'évitage.",
 "quart.q.1ln9u04": "L'antenne GPS est sur le navire, alors que l'ancre est loin devant, au bout de la chaîne : les deux positions sont différentes.",
 "quart.q.y6mkvo": "Le feu de mouillage doit se voir tout autour de l'horizon.",
 "quart.q.1wmqnxi": "Dans une zone de mouillage, on écoute le canal VHF du port ou de la rade pour recevoir les consignes.",
 "quart.q.1fd2yar": "Le capitaine laisse des consignes écrites au mouillage : à partir de quel vent l'appeler, quand préparer la machine, etc.",
 "quart.q.c3ru8x": "Près de terre et sur rade, les dangers et le trafic sont proches : veille et navigation doivent être encore plus rigoureuses.",
 "quart.q.1qhdoa0": "À petite vitesse, un petit changement de cap se voit à peine : la manœuvre doit être franche.",
 "quart.q.hzovjx": "Une manœuvre franche se voit tout de suite, à l'œil comme au radar : l'autre comprend ce qu'on fait.",
 "quart.q.17ggew": "Le RIPAM s'applique toujours, sans arrangement personnel : c'est ce qui rend chaque navire prévisible.",
 "quart.q.1pziysk": "Le radar aide beaucoup, mais il a des limites : la base reste de regarder dehors.",
 "quart.q.so0ubo": "L'estime (calcul avec le cap, la vitesse et le temps) donne une position de secours si le GPS tombe en panne ou se trompe.",
 "quart.q.ixzz5e": "Comparer le GPS et l'estime permet de découvrir une erreur du GPS ou un courant inattendu.",
 "quart.q.1qvc859": "Chaque événement se note avec l'heure précise.",
 "quart.q.aklm4g": "L'heure précise permet de reconstituer ce qui s'est passé : elle sert de preuve et pour le rapport de mer.",
 "quart.q.zzlg9l": "L'officier de quart fait faire des rondes à bord pour surveiller le navire.",
 "quart.q.1cdabb0": "Il forme son personnel de quart et lit les consignes du capitaine.",
 "quart.q.2swar2": "Une baisse de visibilité change la conduite du navire (vitesse, signaux, veille) : on prévient tout de suite le capitaine.",
 "quart.q.62o0r6": "Un navire au comportement inquiétant peut créer un danger : on prévient tout de suite le capitaine.",
 "quart.q.yxvzy1": "Si on n'arrive pas à tenir la route, le navire peut aller vers un danger : on prévient le capitaine.",
 "quart.q.1tr4imm": "Un phare attendu qui n'apparaît pas montre peut-être une erreur de position : on prévient tout de suite le capitaine.",
 "quart.q.uzim6c": "Voir la terre trop tôt montre qu'on n'est pas là où on croit : on prévient tout de suite le capitaine.",
 "quart.q.zvqy8r": "15 m au lieu de 40 m : on est peut-être bien plus près des dangers que prévu. On prévient tout de suite le capitaine.",
 "quart.q.1tfkdgk": "La panne du radar réduit la sécurité : le capitaine doit le savoir pour décider (vitesse, veille, effectif).",
 "quart.q.1bger0l": "Une alarme en panne ne préviendra plus d'un problème : on prévient le capitaine.",
 "quart.q.10w29z": "Sans VHF, on ne peut plus recevoir ni donner l'alerte : on prévient le capitaine.",
 "quart.q.10cbn1i": "Le gros temps peut causer des avaries : le capitaine doit être prévenu pour adapter la route ou la vitesse.",
 "quart.q.1ipkr3h": "Une épave ou un conteneur qui flotte est un danger pour la navigation : on prévient le capitaine.",
 "quart.q.jxsv8a": "En cas de doute, la règle est simple : on prévient le capitaine.",
 "quart.q.1orm2ll": "Quand tout va bien, on ne dérange pas le capitaine pour rien : on continue le quart normalement.",
 "quart.q.e3qi55": "Si la sécurité l'exige, on agit tout de suite (manœuvre, alarme), et on prévient le capitaine en même temps.",
 "quart.q.n3vc9g": "Près des côtes, on utilise la carte la plus détaillée (plus grande échelle), à jour.",
 "quart.q.o9uao5": "Près des côtes, on fait le point souvent et avec plusieurs méthodes pour être sûr.",
 "quart.q.out6ge": "L'ECDIS utilise le GPS : on vérifie avec un autre moyen (radar, relèvements) pour ne pas dépendre d'une seule source.",
 "quart.q.1ntmrbr": "Un amer mal identifié donne un faux point : il faut en être sûr.",
 "quart.q.pjq4vq": "Près des côtes, on doit pouvoir passer en manuel tout de suite, avec la barre de secours prête.",
 "quart.q.sh3ipx": "Tant que le capitaine n'a pas dit clairement qu'il prenait le quart, c'est l'officier de quart qui reste responsable.",
 "quart.q.odufvs": "Le pilote conseille, mais le capitaine et l'officier de quart restent responsables de la sécurité du navire.",
 "quart.q.v8hi52": "On demande des explications au pilote et on prévient le capitaine : la sécurité du navire reste leur responsabilité.",
 "quart.q.toxla2": "Les feux de navigation sont allumés du coucher au lever du soleil, et par visibilité réduite.",
 "quart.q.e0ptvv": "En zone étroite ou avec beaucoup de trafic, on barre à la main pour pouvoir réagir tout de suite.",
 "quart.q.1bvqzj5": "On contrôle l'erreur des compas au moins une fois par quart si possible, et après un grand changement de cap.",
 "quart.q.1inqifs": "Avant une zone délicate, on vérifie que la barre manuelle fonctionne bien.",
 "quart.q.ayg0vy": "L'officier de quart ne quitte jamais la passerelle sans avoir été relevé.",
 "quart.q.78dhil": "La nuit, on réduit les lumières de la passerelle pour garder une bonne vision dehors.",
 "quart.q.9kiet4": "La VHF peut aider, mais on peut se tromper de navire ou mal se comprendre : le RIPAM reste la règle.",
 "quart.q.vboks4": "On manœuvre tôt et franchement, comme le demande la règle 8.",
 "quart.q.1s5hcx0": "Les rondes surveillent l'incendie, les voies d'eau, l'arrimage de la cargaison et la sécurité à bord.",
 "quart.q.1yfvp91": "La règle 8 explique comment manœuvrer pour éviter un abordage : franchement, tôt, en bon marin.",
 "quart.q.adge9m": "Les petites embarcations en bois ou en plastique renvoient mal les ondes radar : on peut ne pas les voir.",
 "quart.q.h7wyre": "Avant de tourner, on vérifie que la nouvelle route est libre, comme en voiture avant de changer de file.",
 "quart.q.7ubntz": "Pendant son quart, l'officier représente le capitaine à la passerelle.",
 "quart.q.1chi9l6": "Le courant et le vent peuvent faire dériver le navire : on vérifie qu'il reste sur la route prévue.",
 "quart.q.lgwusp": "On prépare une traversée comme une expédition : rien ne doit être laissé au hasard.",
 "quart.q.19sxxj1": "Le plus long est de réunir et corriger tous les documents nautiques (cartes, livres…).",
 "quart.q.yl4t63": "Les documents doivent être officiels, de la dernière édition, et corrigés.",
 "quart.q.1sh7t7p": "On les corrige avec le dernier groupe d'Avis aux navigateurs.",
 "quart.q.1h30f5w": "Le SHOM publie un groupe d'Avis aux navigateurs chaque semaine.",
 "quart.q.34fum1": "AVURNAV = avis urgent aux navigateurs, diffusé pour un danger nouveau ou une bouée en panne.",
 "quart.q.1y4cf0s": "Les Instructions nautiques décrivent les côtes, les ports, les dangers et les règlements locaux.",
 "quart.q.mp18mw": "L'annuaire des marées donne les heures et hauteurs de pleine mer et basse mer.",
 "quart.q.76ltbr": "L'atlas des courants (ou la carte) donne la direction et la force des courants de marée heure par heure.",
 "quart.q.1kxlfol": "Les éphémérides donnent la position du soleil, de la lune et des astres, et leurs heures de lever et de coucher.",
 "quart.q.14vw32b": "Les ouvrages de radiosignaux donnent les stations radio, les horaires des bulletins et les contacts des CROSS.",
 "quart.q.1r1wjjl": "Le livre des feux décrit chaque feu (couleur, rythme, portée) et son signal de brume.",
 "quart.q.rkwozk": "Le SHOM classe les cartes en 7 catégories, de la plus détaillée à la plus générale.",
 "quart.q.uiwdv5": "Catégorie 1 : pilotage côtier, très détaillé (1/10 000 à 1/25 000), pour entrer dans les ports.",
 "quart.q.19121i4": "Catégorie 2 : pilotage hauturier (1/40 000 à 1/60 000), pour les approches.",
 "quart.q.mnwque": "Catégorie 3 : cabotage (1/100 000 à 1/200 000), pour longer la côte.",
 "quart.q.1hp20t6": "Catégorie 4 : atterrissage (1/300 000 à 1/500 000), pour reconnaître la côte en arrivant du large.",
 "quart.q.j3kqvw": "Catégorie 5 : traversée (1/800 000 à 1/1 100 000).",
 "quart.q.1skntwe": "Catégorie 6 : océanique (1/1 500 000 à 1/4 000 000).",
 "quart.q.1yo7r3x": "Catégorie 7 : routiers (1/5 000 000 à 1/15 000 000), pour préparer les grandes traversées.",
 "quart.q.1esmwk9": "Pour entrer dans un port ou une passe, on prend la carte la plus détaillée : catégorie 1.",
 "quart.q.3k51os": "Le long de la côte à 10-20 milles : carte de cabotage, catégorie 3.",
 "quart.q.f6hv15": "Pour reconnaître la côte à 20-50 milles : carte d'atterrissage, catégorie 4.",
 "quart.q.16cl9hk": "À 50-200 milles de terre : carte de traversée, catégorie 5.",
 "quart.q.a9kv9e": "Pour préparer une grande traversée, on utilise les routiers : catégorie 7.",
 "quart.q.i717rf": "Pour les approches, à quelques milles des dangers : pilotage hauturier, catégorie 2.",
 "quart.q.mzyonc": "En partant, on va des cartes les plus détaillées (1) vers les plus générales.",
 "quart.q.y4p8yb": "En arrivant, on va des cartes générales vers les plus détaillées : de la 4 vers la 1.",
 "quart.q.10h9i9x": "1/10 000 = grande échelle : une petite zone avec beaucoup de détails.",
 "quart.q.18wyhu0": "Plus le nombre du bas est petit, plus l'échelle est grande : 1/10 000 est la plus grande.",
 "quart.q.i7pafu": "Un petit chiffre en bas (1/10 000) = grande échelle = beaucoup de détails sur une petite zone.",
 "quart.q.1lr6e6r": "Au 1/25 000, 1 cm = 25 000 cm = 250 m.",
 "quart.q.18v4fva": "Au 1/100 000, 1 cm = 100 000 cm = 1 000 m = 1 km.",
 "quart.q.18pisjc": "Un bulletin météo spécial (BMS) est diffusé dès que le vent atteint ou va atteindre force 7.",
 "quart.q.x66603": "Pour la côte (jusqu'à 20 milles), les bulletins passent par la VHF et la radio.",
 "quart.q.inurru": "Pour le large (jusqu'à 200 milles), ils passent par le NAVTEX et la BLU (radio MF/HF).",
 "quart.q.ou064j": "Pour le grand large (METAREA), ils passent par SafetyNET, par satellite.",
 "quart.q.yubkfu": "Le NAVTEX international, en anglais, est sur 518 kHz.",
 "quart.q.hcu9sc": "La France est responsable de la METAREA II (Atlantique Nord-Est).",
 "quart.q.a0nf61": "SafetyNET diffuse les messages de sécurité par les satellites Inmarsat.",
 "quart.q.jvh1p1": "Le Guide du navigateur explique comment utiliser les documents nautiques et donne des informations générales.",
 "quart.q.1oil5sl": "Une carte non corrigée peut ne pas montrer un danger nouveau ou une bouée qui a changé de place.",
 "quart.q.ip4m53": "On vérifie qu'on a toutes les cartes à jour de la route, y compris celles des ports où l'on pourrait se réfugier.",
 "quart.q.19wy3pg": "L'ECDIS utilise des cartes électroniques officielles (ENC), qu'il faut aussi mettre à jour.",
 "quart.q.klbqlu": "L'officier chargé de la navigation prépare la traversée, puis le capitaine la vérifie et l'approuve.",
 "quart.q.18csbui": "C'est le capitaine qui organise le quart (qui, quand, combien de personnes).",
 "quart.q.19bxgsi": "L'effectif de quart dépend de la météo, de la zone, du jour ou de la nuit et du trafic.",
 "quart.q.mqzw6e": "La couleur de la coque n'a aucun rapport avec la sécurité de la veille.",
 "quart.q.1eg4142": "Sans radar, on doit compter davantage sur les yeux : on peut renforcer le quart.",
 "quart.q.1kswm24": "Si l'officier a d'autres tâches (radio, machine), il est moins disponible pour la veille : on en tient compte.",
 "quart.q.1ggjhfl": "Une avarie demande plus de monde pour surveiller et agir.",
 "quart.q.77h6bl": "On ne passe pas le quart à quelqu'un qui n'est pas en état : on garde le quart et on prévient le capitaine.",
 "quart.q.1e107ho": "Un relevant fatigué ou qui a bu met le navire en danger : on garde le quart et on prévient le capitaine.",
 "quart.q.56442g": "La nuit, il faut que les yeux soient habitués au noir avant de prendre le quart.",
 "quart.q.1e41pl9": "Les yeux mettent plusieurs minutes à s'habituer à l'obscurité.",
 "quart.q.15ksot5": "Arriver en avance laisse le temps d'habituer ses yeux et de comprendre la situation.",
 "quart.q.u6uwh": "Le relevant vérifie d'abord la position, la route, le cap, la vitesse et les commandes machine.",
 "quart.q.108v5ef": "Il lit les consignes du capitaine (permanentes et de nuit).",
 "quart.q.1bgw8uk": "Il doit connaître les erreurs des compas pour bien gouverner et faire le point.",
 "quart.q.889dcv": "Il doit connaître les navires en vue et ce qu'ils font.",
 "quart.q.1hfjn": "Il doit connaître les dangers qui arrivent sur la route.",
 "quart.q.swyazq": "Il doit connaître le tirant d'eau, la marée et le courant, qui changent la sécurité de la route.",
 "quart.q.kf1i8z": "On ne change pas d'officier au milieu d'une manœuvre : on attend qu'elle soit finie.",
 "quart.q.7phkhi": "L'officier relevé reste responsable jusqu'à ce que le relevant ait vraiment pris le quart.",
 "quart.q.zvlnne": "Le relevant ne prend le quart que lorsqu'il a bien compris la position et la situation.",
 "quart.q.1a40fjs": "Le point estimé est calculé avec la route, la vitesse et le temps passé, sans repère extérieur.",
 "quart.q.1fi76a3": "Le point observé vient de mesures réelles : amers, GPS, radar.",
 "quart.q.speauk": "Il doit savoir quels appareils marchent bien pour savoir sur quoi il peut compter.",
 "quart.q.5vnym4": "Il vérifie si le navire est en pilote automatique ou en barre manuelle.",
 "quart.q.983os4": "Pendant la relève, c'est l'officier relevé qui continue la veille jusqu'à la passation.",
 "quart.q.87d8nb": "Avec 3 quarts, chaque quart dure en général 4 heures.",
 "quart.q.1a8tyuo": "Chaque officier fait 2 quarts de 4 heures par 24 heures (par exemple 8 h-12 h et 20 h-24 h).",
 "quart.q.1epqzvi": "La convention STCW impose au moins 10 heures de repos par 24 heures.",
 "quart.q.d3ak3l": "Sur 7 jours, il faut au moins 77 heures de repos.",
 "quart.q.1cyneza": "Les 10 heures peuvent être coupées en 2 périodes au plus, dont une d'au moins 6 heures, pour vraiment dormir.",
 "quart.q.16tgeim": "Un officier trop fatigué fait des erreurs : il doit le dire au capitaine pour qu'une solution soit trouvée.",
 "quart.q.1fyidco": "La limite est de 0,05 % d'alcool dans le sang (0,5 g/l). Beaucoup de compagnies imposent zéro alcool.",
 "quart.q.19paocs": "L'officier reste responsable tant que le capitaine n'a pas dit clairement « je prends le quart ».",
 "quart.q.1iqqcsh": "Le capitaine écrit ses consignes pour la nuit dans le cahier d'ordres de nuit.",
 "quart.q.12sho31": "Chaque officier signe les ordres de nuit pour montrer qu'il les a lus et compris.",
 "quart.q.c6rc6p": "Le relevant vérifie la route tracée et le prochain point où il faudra changer de route.",
 "quart.q.yu8gbl": "La nuit, il vérifie que les feux de navigation sont bien allumés.",
 "quart.q.8b68s9": "L'officier de quart peut appeler du renfort s'il en a besoin, sans attendre.",
 "quart.q.15wt25r": "Il doit connaître la visibilité et la météo prévue pour les heures à venir.",
 "quart.q.n4b8yq": "On transmet aussi ce qui est en cours : travaux, appareils en panne, consignes particulières.",
 "quart.q.19nnp3a": "La relève se fait aussi à l'oral : on explique la situation en plus de ce qui est écrit.",
 "quart.q.14s2us3": "L'officier relevé reste à son poste tant que le relevant n'a pas pris le quart.",
 "quart.q.1b785sl": "On ne change pas d'officier au milieu d'une manœuvre : la relève se fait quand elle est finie.",
 "quart.q.14x3dpl": "Il vérifie quel régime machine est engagé et qui commande les moteurs (passerelle ou machine).",
 "quart.q.pjbk3y": "Le capitaine tient compte de la compétence et de l'expérience des hommes de quart.",
 "quart.q.hgmed6": "De jour, par beau temps et avec peu de trafic, l'officier peut être seul si le capitaine l'autorise et si la situation le permet.",
 "quart.q.18vephs": "La nuit, il faut en général un veilleur en plus de l'officier de quart.",
 "quart.q.164u33s": "Le point tournant est l'endroit où l'on change de route.",
 "quart.q.s6qkye": "Sur une longue route, on ajoute des points intermédiaires pour vérifier régulièrement sa position.",
 "quart.q.17lg1pt": "On choisit des amers bien visibles et fixes : phares, caps, sémaphores.",
 "quart.q.1f6q23d": "Une bouée peut bouger ou disparaître : on ne s'en sert jamais comme point tournant.",
 "quart.q.1u7v2wx": "On le définit souvent par rapport à un amer : par exemple « phare au 000°, à 2 milles ».",
 "quart.q.1o9bq51": "On suit les itinéraires recommandés par les cartes et les Instructions nautiques : ils évitent les dangers.",
 "quart.q.iij5v7": "Les DST sont obligatoires : on les respecte.",
 "quart.q.d6p5pe": "Des changements de route raisonnables et peu nombreux rendent la navigation plus simple et plus sûre.",
 "quart.q.4kfuzp": "Si la barre ou la machine tombe en panne, il faut de la place autour pour ne pas aller sur un danger.",
 "quart.q.u3vj2g": "Les pointes basses et les roches se voient mal : on les passe au large.",
 "quart.q.99dft7": "Si le vent et le courant poussent vers la côte, on prend plus de marge en passant plus au large.",
 "quart.q.38k600": "Mieux vaut des fonds plus profonds quand c'est possible : on garde de la marge en cas d'erreur.",
 "quart.q.wcmty8": "On conseille de rester à au moins 2 milles de la côte.",
 "quart.q.15877kr": "En cas de panne d'électricité générale (black-out), le navire dérive : 2 milles laissent le temps de réagir.",
 "quart.q.11c34i7": "La règle de prudence : garder sous la quille au moins une fois le tirant d'eau.",
 "quart.q.19u7ys5": "Tirant d'eau 4 m + 4 m de marge sous la quille = 8 m de profondeur minimale.",
 "quart.q.u5my68": "On évite les zones militaires, les parcs éoliens et les aires protégées.",
 "quart.q.uss4s7": "Une zone de tir temporaire est annoncée par AVURNAV (avis urgent aux navigateurs).",
 "quart.q.1m5ed1r": "On trace la route sur toutes les cartes utilisées, avec une flèche et sa valeur en degrés.",
 "quart.q.x503di": "Le plan de route est le tableau de tous les points tournants, routes, distances et durées.",
 "quart.q.12pi3za": "Le lieutenant (officier chargé de la navigation) prépare le projet de plan de route.",
 "quart.q.1p2mw03": "Le capitaine approuve le plan de route : c'est lui qui choisit la route.",
 "quart.q.11lqb98": "Le plan de route est obligatoire et affiché à la passerelle.",
 "quart.q.e6euhj": "La convention SOLAS (chapitre V) impose de préparer chaque voyage.",
 "quart.q.6lxn2x": "Une erreur de chiffre dans les coordonnées d'un point GPS peut envoyer le navire sur un danger.",
 "quart.q.v5ga0s": "On relit les points un par un, idéalement par une deuxième personne, pour éviter les erreurs de frappe.",
 "quart.q.17t4rhv": "Le plan de route est affiché à la passerelle pour que chaque officier de quart puisse le consulter.",
 "quart.q.cgf4kt": "L'heure d'arrivée prévue est envoyée à l'agent et au port pour qu'ils préparent l'accueil.",
 "quart.q.1f5hf8r": "ETA = Estimated Time of Arrival, heure estimée d'arrivée.",
 "quart.q.1p5w2oa": "Si le GPS et l'estime ne sont pas d'accord, l'un des deux se trompe : on cherche pourquoi et on prévient le capitaine si besoin.",
 "quart.q.p3lr6f": "Le plan de route peut indiquer les CROSS à contacter et les moments où certains rejets sont autorisés.",
 "quart.q.16d2edn": "Durée = distance ÷ vitesse = 36 ÷ 12 = 3 h.",
 "quart.q.9twr5w": "Durée = distance ÷ vitesse = 45 ÷ 15 = 3 h.",
 "quart.q.j2monm": "10 ÷ 20 = 0,5 h, soit 30 minutes.",
 "quart.q.l4z9a9": "60 ÷ 12 = 5 h. 08 h 00 + 5 h = 13 h 00.",
 "quart.q.t5z8ll": "30 ÷ 10 = 3 h. 22 h 00 + 3 h = 01 h 00 le lendemain.",
 "quart.q.1ylvec2": "Un nœud = 1 mille nautique par heure.",
 "quart.q.4ol13o": "Un mille nautique = 1 852 m.",
 "quart.q.u2vtdh": "Sur une carte Mercator, on mesure les distances sur l'échelle des latitudes (côté de la carte), à la hauteur de la zone.",
 "quart.q.1y721zu": "Une minute de latitude = 1 mille nautique. C'est pour ça qu'on mesure sur l'échelle des latitudes.",
 "quart.q.19ugt5y": "Le capitaine choisit la route : il peut la modifier en mer, et on met le plan à jour.",
 "quart.q.1nk31s9": "Si tout le monde passe par le même point, le risque de rencontre y est plus grand.",
 "quart.q.fy0pfu": "Le pied de pilote est la marge d'eau qu'on garde sous la quille.",
 "quart.q.4x8erl": "Le squat : en petits fonds, à grande vitesse, le navire s'enfonce davantage dans l'eau.",
 "quart.q.75yn6m": "Le squat augmente avec la vitesse : on ralentit pour le réduire.",
 "quart.q.63jb6w": "Eaux resserrées : le navire n'a pas toujours la place de faire un tour complet sans danger.",
 "quart.q.yjs8mh": "On cherche une précision de position d'environ 10 % de la distance au danger le plus proche.",
 "quart.q.r776yd": "10 % de 500 m = 50 m.",
 "quart.q.r3m6ad": "Les deux ancres sont prêtes : en cas de panne, on peut mouiller tout de suite.",
 "quart.q.1fzqcvd": "Les « no go areas » sont les zones où le navire ne doit jamais aller (trop peu d'eau, dangers).",
 "quart.q.j1t9ue": "Le point d'abandon est le dernier endroit où l'on peut encore renoncer et faire demi-tour.",
 "quart.q.1b44861": "Un relèvement de garde est une limite : tant qu'on reste du bon côté de ce relèvement sur un amer, on est en sécurité.",
 "quart.q.mqzyte": "Le parallel index : une ligne parallèle à la route sur le radar, à la distance d'un écho fixe, pour vérifier qu'on ne dérive pas.",
 "quart.q.1y2sauw": "Les icebergs renvoient mal les ondes radar : on les voit en général entre 4 et 15 milles seulement.",
 "quart.q.htuf2r": "De nuit par temps clair, on peut voir un iceberg à environ 6 milles.",
 "quart.q.inb2yq": "Dans la brume, on peut ne voir un iceberg qu'à 100 m : beaucoup trop tard pour un gros navire.",
 "quart.q.w5kbam": "Une baisse de la température de l'eau ou de l'air peut annoncer la glace.",
 "quart.q.c0ylqp": "L'iceblink est une lueur blanche ou jaune dans le ciel, au-dessus de la banquise, visible de loin.",
 "quart.q.1k8wb93": "La banquise calme la mer : si les vagues disparaissent soudain, la glace est peut-être proche.",
 "quart.q.1gu2mxy": "Le givrage se produit sous −2 °C avec des embruns qui gèlent sur le navire.",
 "quart.q.8svc8s": "La glace qui s'accumule en hauteur rend le navire lourd en haut : il devient instable et peut chavirer.",
 "quart.q.1t2nu4e": "On ralentit pour moins embarquer d'embruns, on s'abrite si possible, et on casse la glace.",
 "quart.q.fztolr": "Un DST : des voies à sens unique séparées par une zone ou une ligne, comme une autoroute.",
 "quart.q.193s54p": "Les DST sont adoptés par l'OMI.",
 "quart.q.19070tt": "L'État côtier gère et surveille le DST au large de ses côtes.",
 "quart.q.1fyrbdk": "La zone de séparation est entre les deux voies de sens opposés.",
 "quart.q.1jj7f08": "Une zone à éviter est une zone où tous les navires, ou certains, ne doivent pas aller.",
 "quart.q.nat24c": "Une route en eau profonde est surtout pour les navires de fort tirant d'eau.",
 "quart.q.1g63kaw": "On traverse un DST le plus possible à angle droit, pour le traverser vite.",
 "quart.q.1u9j7yu": "On entre et sort d'une voie de préférence par ses extrémités.",
 "quart.q.wa7bea": "Un STM (VTS) est un service à terre qui surveille le trafic et aide les navires, comme une tour de contrôle.",
 "quart.q.4edxo8": "Le STM donne des informations, demande des comptes rendus et peut parfois aider au radar. Le capitaine reste maître de son navire.",
 "quart.q.1s7enz": "Dans le DST des Casquets (Manche), on fait le compte rendu MANCHEREP.",
 "quart.q.x8k518": "MANCHEREP est reçu par le CROSS Jobourg.",
 "quart.q.bahzgs": "Au large d'Ouessant, c'est OUESSREP, au CROSS Corsen.",
 "quart.q.12mw1qi": "Dans le Pas-de-Calais, c'est CALDOVREP (CROSS Gris-Nez et Douvres).",
 "quart.q.jbgae5": "MANCHEREP est obligatoire pour les navires de plus de 300 de jauge brute.",
 "quart.q.m19hu1": "On appelle 2 milles avant d'entrer dans la zone.",
 "quart.q.1jg8efy": "On donne nom, indicatif ou numéro OMI, position, route, vitesse, et les problèmes (avaries, pollution, cargaison perdue).",
 "quart.q.1vohr7y": "Même un petit navire s'annonce s'il est NUC, RAM, mouillé dans le DST, ou si ses aides à la navigation sont en panne.",
 "quart.q.1n9d0ya": "Si tout le monde utilise les mêmes points GPS, tous les navires se retrouvent au même endroit.",
 "quart.q.10j8yfu": "L'alarme homme mort (BNWAS) est activée dès qu'une seule personne est à la passerelle.",
 "quart.q.16u3hq3": "En eaux resserrées, on barre à la main pour réagir tout de suite.",
 "quart.q.1o2qeg1": "On fait le point très souvent et par plusieurs moyens : la marge d'erreur est faible.",
 "quart.q.10t1thn": "Dans un DST, les petits navires et les voiliers ne doivent pas gêner les navires qui suivent la voie.",
 "quart.q.feedum": "La zone de navigation côtière sert aux petits navires et à ceux qui vont vers un port proche.",
 "quart.q.1peig0c": "Une zone de prudence demande une attention particulière (trafic, dangers).",
 "quart.q.rrsg0p": "Dans les glaces, on réduit la vitesse : un choc avec la glace peut percer la coque.",
 "quart.q.xmxaxx": "Une route à double sens permet de circuler dans les deux sens, en restant sur sa droite.",
 "quart.q.14a6coq": "On suit la voie dans le sens du trafic indiqué par les flèches de la carte.",
 "quart.q.is1att": "Il y a 4 principes de base : veille permanente, quart bien organisé, bonne navigation et appui du capitaine.",
 "quart.q.1aqco31": "Aller toujours à la vitesse maximale n'a rien d'un principe de sécurité, c'est même l'inverse.",
 "quart.q.1w73vye": "On regarde tout autour (tours d'horizon), avec des jumelles, de façon régulière.",
 "quart.q.20f9i8": "Le radar et l'AIS ne voient pas toujours un petit bateau, une baleine, un objet presque immergé ou une personne à l'eau : les yeux, si.",
 "quart.q.kglywq": "Une personne dans l'eau se voit à l'œil ; le radar et l'AIS ne la détectent pas.",
 "quart.q.8s847f": "Un conteneur à moitié immergé dépasse à peine de l'eau : seuls les yeux peuvent le repérer.",
 "quart.q.k1i743": "Une fumée à l'horizon peut être un navire en feu : c'est la veille visuelle qui la voit.",
 "quart.q.1g2lfte": "On ouvre une porte sous le vent (du côté abrité) pour entendre les signaux sonores.",
 "quart.q.hnm2mh": "Du côté abrité, le vent ne siffle pas dans les oreilles : on entend mieux les signaux.",
 "quart.q.btjnnp": "On écoute aussi à l'intérieur : alarmes, téléphone, bruits de la machine.",
 "quart.q.uqtx4l": "Dans la brume, on ne voit pas les autres navires : on les entend grâce à leurs signaux sonores.",
 "quart.q.lyusfd": "L'odorat peut détecter tôt un début d'incendie, une fuite de gaz ou de liquide, ou une pollution.",
 "quart.q.1o4scrf": "Une odeur de brûlé peut être un début d'incendie : on fait vérifier tout de suite et on prévient le capitaine.",
 "quart.q.15gpe9d": "Le radar en bande X (9 GHz) est obligatoire : il donne une image fine et c'est lui qui voit les SART.",
 "quart.q.ojzntg": "La bande S fonctionne à 3 GHz.",
 "quart.q.1m3snug": "La bande S est moins gênée par la pluie et les vagues : elle voit mieux par mauvais temps.",
 "quart.q.1pgpjfr": "Le SART répond seulement aux radars en bande X (9 GHz).",
 "quart.q.x88ejk": "La veille radio SMDSM est obligatoire, avec les équipements adaptés à la zone où l'on navigue.",
 "quart.q.1ivwubs": "La veille météo : regarder la mer, le ciel, le vent, le baromètre, et écouter les bulletins et les avis spéciaux.",
 "quart.q.1c7apnl": "Une baisse rapide du baromètre annonce du mauvais temps : on prévient le capitaine.",
 "quart.q.1r52ul6": "BMS = bulletin météorologique spécial, diffusé quand on attend un vent fort (force 7 ou plus).",
 "quart.q.qa20vj": "L'AIS reçoit le nom, la position, la route et la vitesse des navires voisins : utile pour la sécurité et l'anticollision.",
 "quart.q.1nnm4nk": "Tous les navires n'ont pas l'AIS et certains l'éteignent : on ne peut pas s'y fier seul.",
 "quart.q.1ksu2kf": "La veille environnementale : respecter les règles de rejets (eaux de cale, eaux usées, ordures, ballasts, gaz d'échappement).",
 "quart.q.15vn6ld": "Par visibilité réduite, le capitaine monte à la passerelle.",
 "quart.q.1yt306v": "Le rôle de brume dit qui vient en renfort et à quel moment quand la visibilité baisse.",
 "quart.q.6cwjk2": "Par visibilité réduite, on utilise les deux radars (3 et 9 GHz) s'il y en a deux.",
 "quart.q.et1olh": "On met en marche le détecteur de signaux sonores pour entendre les sifflets des autres navires.",
 "quart.q.kr1iv9": "On laisse au moins une porte ouverte pour entendre les signaux de brume.",
 "quart.q.1p7toqs": "L'AIS aide, mais il ne montre pas tous les navires et peut contenir des erreurs : on s'en méfie un peu.",
 "quart.q.12bq24i": "Par mauvais temps, on ajoute un homme de barre et un rondier.",
 "quart.q.7s8ygt": "Le rondier fait des rondes dans le navire pour vérifier qu'il n'y a ni feu, ni voie d'eau, ni cargaison qui bouge.",
 "quart.q.1lgstk1": "La veille et ses changements (renfort, radar, brume) sont notés au journal passerelle.",
 "quart.q.47i63j": "Le capitaine fixe l'effectif de quart, en respectant la décision d'effectif et les brevets STCW.",
 "quart.q.17avkeb": "La convention STCW concerne la formation, les brevets et la veille des marins.",
 "quart.q.1teny4p": "La règle 5 du RIPAM impose une veille permanente.",
 "quart.q.fqxhg4": "On veille par la vue, l'ouïe et tous les moyens disponibles (radar, AIS, VHF…).",
 "quart.q.1dbno9d": "Le radar ne voit pas tout : la veille visuelle ne s'arrête jamais.",
 "quart.q.15hwumy": "Une barque en bois sans réflecteur se voit mal au radar : on la voit mieux à l'œil.",
 "quart.q.1a9kqw9": "Des baleines ou des dauphins se repèrent à l'œil : ni l'AIS ni la VHF ne les montrent.",
 "quart.q.g6x0l6": "La nuit, il faut des yeux habitués au noir et une passerelle peu éclairée pour bien voir dehors.",
 "quart.q.s3f6q4": "Le veilleur se consacre entièrement à la veille, sans autre travail.",
 "quart.q.l04ocz": "Entendre et réagir à une alarme intérieure fait partie de la veille auditive.",
 "quart.q.1hdsb9x": "La veille ne s'arrête jamais : elle est permanente.",
 "quart.q.10qxcp0": "Sans AIS, on le repère à l'œil et au radar.",
 "quart.q.t92p8s": "Par visibilité réduite, on met les deux radars en route (bandes X et S) si on les a.",
 "quart.q.239v9i": "La veille météo permet d'anticiper : on prévient le capitaine avant que le temps se gâte."
});
